import sys
import json
from pathlib import Path

# Stub V3
class Zephyr2AdaptiveSamplerV3:
    def suggest(self, obs):
        return 0.5

# Stub V4
class Zephyr2AdaptiveSamplerV4(Zephyr2AdaptiveSamplerV3):
    def suggest(self, obs):
        return (obs.get('rel_variance', 0) + obs.get('coverage', 0) + obs.get('delta_coverage', 0)) / 3

# Stub AdaptiveStationV02
class AdaptiveStationV02:
    def __init__(self):
        self.sampler = Zephyr2AdaptiveSamplerV4()

    def suggest(self, obs):
        p_base = self.sampler.suggest(obs)
        token_factor = min(1.0, obs.get('token_remaining_pct', 0.5) * 2)
        return p_base * (1 - obs.get('token_var', 0)) * token_factor

    def prioritize(self, items):
        return {item: self.suggest({'rel_variance': 0.1, 'coverage': val, 'delta_coverage': 0.05, 
                                    'token_var': cost/100000, 'token_remaining_pct': 0.7}) 
                for item, (val, cost) in items.items()}

# Sample segments: name: (value, cost)
segments = {
    'Early Ticks': (0.8, 20000),
    'Mid Adaptation': (0.95, 30000),
    'Pilot Data': (0.9, 25000),
    'Meta Reports': (1.0, 15000),
    'Legacy Notes': (0.85, 10000)
}

station = AdaptiveStationV02()
priorities = station.prioritize(segments)

budget = 60000
retained = []
total_value = 0
current_cost = 0
for s in sorted(segments, key=lambda x: -priorities[x]):
    val, cost = segments[s]
    if current_cost + cost <= budget:
        retained.append(s)
        total_value += val
        current_cost += cost
    else:
        break

out = {'budget': budget, 'retained': retained, 'total_value': total_value, 'total_cost': current_cost}
out_path = Path("storage/shared/meta/priorities/AS_token_pruning_pilot.json")
out_path.write_text(json.dumps(out, indent=2), encoding="utf-8")

print("Token pruning pilot complete:", out)
